  padding:16px 18px;
  box-shadow:var(--sh-sm);
}
.bt-summary-title{
  font-size:14px;
  font-weight:500;
  text-transform:capitalize;
  color:var(--t3);
  margin-bottom:10px;
}
.bt-summary-row{
  display:flex;
  justify-content:space-between;
  align-items:center;
  padding:8px 0;
  border-bottom:1px solid var(--border);
}
.bt-summary-row:last-child{border-bottom:none;padding-bottom:0}
.bt-summary-label{
  font-size:14px;
  font-weight:500;
  color:var(--t2);
}
.bt-summary-value{
  font-size:15px;
  font-weight:700;
  color:var(--t1);
}
.bt-net-positive{color:var(--green)}
.bt-net-negative{color:var(--red)}
/* CTA Section */
.bt-cta{
  background:#082753;
  border-radius:var(--r-lg);
  padding:28px;
  text-align:center;
}
.bt-cta-content{position:relative;z-index:1}
.bt-cta-check{
  font-size:15px;
  font-weight:600;
  color:#059669;
  margin-bottom:10px;
}
.bt-cta-check span{
  font-weight:700;
  color:#059669;
}
.bt-cta-title{
  font-size:20px;
  font-weight:700;
  color:#fff;
  margin-bottom:8px;
  line-height:1.3;
}
.bt-cta-subtitle{
  font-size:14px;
  color:rgba(255,255,255,.70);
  margin-bottom:18px;
  line-height:1.5;
}
.bt-cta-btn{
  font-family:var(--ff);
  cursor:pointer;
  transition:all .18s;
  text-decoration:none;
  box-shadow:0 3px 12px rgba(5,186,254,.3);
  margin-bottom:14px;
}
.bt-cta-btn {
    color: #fff;
    background-image: linear-gradient(90deg, #21cfff, #019ae6);
    border-color: #21cfff;
    text-align: center;
    white-space: nowrap;
    background-color: #082753;
    border: 1px #082753;
    border-radius: 10px;
    justify-content: center;
    align-self: stretch;
    align-items: center;
    width: auto;
    padding: 10px 24px;
    font-family: Roobert PRO, Arial, sans-serif;
    font-size: 16px;
    font-weight: 700;
    line-height: 24px;
    text-decoration: none;
    display: inline-flex;
}
.bt-cta-btn:hover{
  background:#fff;
  color: #082753;
  transform:translateY(-1px);
  box-shadow:0 6px 18px rgba(5,186,254,.35);
}
.bt-cta-footer{
  font-size:13px;
  color:rgba(255,255,255,.65);
  margin-bottom:14px;
}
.bt-cta-link{
  color:var(--blue);
  text-decoration:none;
  font-weight:600;
  transition:color .15s;
}
.bt-cta-link:hover{
  color:#fff;
}
.bt-cta-trust{
  display:flex;
  align-items:center;
  justify-content:center;
  gap:18px;
  flex-wrap:wrap;
  font-size:12px;
  color:rgba(255,255,255,.55);
  font-weight:500;
}
/* Responsive */
@media(max-width:900px){
  .bt-cols{grid-template-columns:1fr}
  .bt-left{border-right:none;border-bottom:1px solid var(--border)}
  .bt-metrics{grid-template-columns:1fr}
  .bt-presets{flex-direction:column;max-width:360px;margin-left:auto;margin-right:auto}
  .bt-preset{justify-content:center}
}
@media(max-width:640px){
  .bt-section{padding:60px 20px 72px}
  .bt-left,.bt-right{padding:28px 20px}
  .bt-h2{font-size:28px}
  .bt-desc{font-size:15px}
  .bt-hero-amount{font-size:38px}
  .bt-metric-val{font-size:22px}
  .bt-billing{flex-direction:column;gap:4px;padding:4px}
  .bt-bill-btn{padding:10px;font-size:14px}
  .bt-cta-title{font-size:18px}
  .bt-cta-subtitle{font-size:13px}
  .bt-cta-trust{flex-direction:column;gap:6px}
  .bt-label {font-size: 14px;}
}
