                      <div class="bt-cta-check" id="ctaCheck">
                        ✅ You could save <span id="ctaSavingsDisplay">$0</span> this year
                      </div>
                      <div class="bt-cta-title" id="ctaTitle">Ready to start saving?</div>
                      <div class="bt-cta-subtitle">Book a free 15-min demo and we'll walk through your exact numbers — no commitment, no pressure.</div>
                      <a href="https://boldteq.com/book-a-demo" class="bt-cta-btn" onclick="fireCTA()">
                        <span>Schedule a Free Demo →</span>
                      </a>
                      <div class="bt-cta-footer">
                        <span>Have questions? <a href="https://boldteq.com/contact" class="bt-cta-link">Chat with our team →</a></span>
                      </div>
                      <div class="bt-cta-trust">
                        <span>🔒 No credit card</span>
                        <span>📅 15-min call</span>
                        <span>↩️ Cancel anytime</span>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
        <script>
/* ─── Data ───────────────────────────────────────────────────────────── */
const PLANS = {
  starter: { monthly: 999,  quarterly: 899, annual: 799 },
  growth:  { monthly: 1999, quarterly: 1799, annual: 1599 },
  pro:     { monthly: 3499, quarterly: 3149, annual: 2799 }
};
const PRESETS = {
  startup: {
    teamSize: 8,
    manualHours: 6,
    hourlyRate: 50,
    toolCost: 8000,
    plan: 'starter'
  },
  midsize: {
    teamSize: 30,
    manualHours: 8,
    hourlyRate: 60,
    toolCost: 25000,
    plan: 'growth'
  },
  enterprise: {
    teamSize: 100,
    manualHours: 10,
    hourlyRate: 75,
    toolCost: 80000,
    plan: 'pro'
  }
};
const PLAN_DEFAULTS = {
  starter: {
    teamSize: 8,
    manualHours: 6,
    hourlyRate: 50,
    toolCost: 8000
  },
  growth: {
    teamSize: 30,
    manualHours: 8,
    hourlyRate: 60,
    toolCost: 25000
  },
  pro: {
    teamSize: 100,
    manualHours: 10,
    hourlyRate: 75,
    toolCost: 80000
  }
};
/* ─── State ──────────────────────────────────────────────────────────── */
let billing = 'monthly';
let plan = 'growth';
let interacted = false;
let firstResult = false;
let results = {};
/* ─── Helpers ────────────────────────────────────────────────────────── */
const g = id => document.getElementById(id);
const usd = v => '$' + Math.round(v).toLocaleString('en-US');
const pct = v => Math.round(v) + '%';
const num = v => Math.round(v).toLocaleString('en-US');
function fillTrack(el) {
  const min = parseFloat(el.min) || 0;
  const max = parseFloat(el.max) || 100;
  const val = parseFloat(el.value) || 0;
  const pct = ((val - min) / (max - min)) * 100;
  el.style.background = `linear-gradient(to right, var(--blue) 0%, var(--blue) ${pct}%, #e5e7eb ${pct}%, #e5e7eb 100%)`;
}
/* ─── Analytics ──────────────────────────────────────────────────────── */
function fire(name, props) {
  try { if (window.gtag) window.gtag('event', name, props); } catch (e) {}
  try { if (window.analytics) window.analytics.track(name, props); } catch (e) {}
  console.log('[BoldTeq ROI]', name, props || '');
}
/* ─── Calculations ───────────────────────────────────────────────────── */
function calc() {
  const ts = +g('teamSize').value || 0;
  const mh = +g('manualHours').value || 0;
  const hr = +g('hourlyRate').value || 0;
  const tc = +g('toolCost').value || 0;
  // Get the monthly cost based on billing period
  let bmo;
  if (billing === 'monthly') {
    bmo = PLANS[plan].monthly;
  } else if (billing === 'quarterly') {
    bmo = PLANS[plan].quarterly;
  } else {
    bmo = PLANS[plan].annual;
  }
  const byr = bmo * 12;
  const laborSaved = mh * hr * ts * 52;
  const savings = laborSaved + tc;
  const net = savings - byr;
  const roi = byr > 0 ? (net / byr) * 100 : 0;
  const monthlyBenefit = (savings / 12) - bmo; // Monthly savings minus monthly cost
  const hrsSaved = mh * ts * 52;
  const totalHrs = 40 * ts * 52;
  const prodGain = totalHrs > 0 ? (hrsSaved / totalHrs) * 100 : 0;
  return { savings, net, roi, monthlyBenefit, hrsSaved, prodGain, bmo, byr, ts, mh, hr, tc };
}
/* ─── Animated Counter ───────────────────────────────────────────────── */
const rafMap = {};
function animTo(el, to, fmt) {
  const from = parseFloat(el.dataset.v || 0);
  el.dataset.v = to;
  cancelAnimationFrame(rafMap[el.id]);
  const t0 = performance.now(), dur = 500;
  (function step(ts) {
    const p = Math.min((ts - t0) / dur, 1), e = 1 - Math.pow(1 - p, 3);
    el.textContent = fmt(from + (to - from) * e);
    if (p < 1) rafMap[el.id] = requestAnimationFrame(step);
    else el.textContent = fmt(to);
  })(performance.now());
}
/* ─── Render ─────────────────────────────────────────────────────────── */
function render() {
  const r = calc();
  results = r;
  /* slider labels + fills */
  g('teamSizeVal').textContent = num(+g('teamSize').value);
  g('manualHoursVal').textContent = g('manualHours').value + ' hrs';
  fillTrack(g('teamSize'));
  fillTrack(g('manualHours'));
  /* hero */
  animTo(g('heroSavings'), r.savings, v => usd(v));
  g('heroPct').textContent = pct(r.roi) + ' ROI';
  /* metric cards */
  animTo(g('monthlyBenefitVal'), r.monthlyBenefit, v => (v >= 0 ? '+' : '') + usd(v));
  g('monthlyBenefitVal').style.color = r.monthlyBenefit >= 0 ? 'var(--green)' : 'var(--red)';
  animTo(g('hoursVal'), r.hrsSaved, v => r.hrsSaved > 0 ? num(v) + ' hrs' : '—');
  animTo(g('prodVal'), r.prodGain, v => r.prodGain > 0 ? v.toFixed(1) + '%' : '—');
  animTo(g('netVal'), r.net, v => (v >= 0 ? '+' : '') + usd(v));
  g('netVal').style.color = r.net >= 0 ? 'var(--green)' : 'var(--red)';
  g('netMetric').className = 'bt-metric' + (r.net >= 0 ? ' highlight' : '');
  /* plan strip */
  g('planLine').textContent = usd(r.bmo) + '/mo · ' + usd(r.byr) + '/yr';
  g('netGainLine').textContent = (r.net >= 0 ? '+' : '') + usd(r.net);
  g('netGainLine').className = r.net >= 0 ? 'bt-net-positive' : 'bt-net-negative';
  /* plan prices */
  ['starter', 'growth', 'pro'].forEach(k => {
    const cap = k[0].toUpperCase() + k.slice(1);
    let price;
    if (billing === 'monthly') {
      price = PLANS[k].monthly;
    } else if (billing === 'quarterly') {
      price = PLANS[k].quarterly;
    } else {
      price = PLANS[k].annual;
    }
    g('price' + cap).textContent = usd(price) + '/mo';
  });
  /* CTA — dynamic savings display */
  if (r.savings > 0) {
    g('ctaSavingsDisplay').textContent = usd(r.savings);
    g('ctaCheck').style.display = 'block';
    g('ctaTitle').textContent = `Ready to unlock ${usd(r.savings)} in savings?`;
  } else {
    g('ctaCheck').style.display = 'none';
    g('ctaTitle').textContent = 'Ready to start saving?';
  }
  /* validation */
  g('rateErr').style.display = +g('hourlyRate').value < 10 ? 'block' : 'none';
  g('toolErr').style.display = +g('toolCost').value < 0 ? 'block' : 'none';
  /* first-result analytics */
  if (interacted && !firstResult && r.savings > 0) {
    firstResult = true;
    fire('roi_calculator_result', {
      team_size: r.ts,
      manual_hours_week: r.mh,
      hourly_rate: r.hr,
      estimated_savings: Math.round(r.savings),
      roi_percent: Math.round(r.roi),
      monthly_benefit: Math.round(r.monthlyBenefit),
      plan_type: plan,
      billing_period: billing,
    });
  }
}
/* ─── Handlers ───────────────────────────────────────────────────────── */
function onInput() {
  if (!interacted) {
    interacted = true;
    fire('roi_calculator_start');
  }
  render();
}
function setBilling(b) {
  billing = b;
  g('billMonthly').classList.toggle('active', b === 'monthly');
  g('billMonthly').setAttribute('aria-pressed', b === 'monthly');
  g('billQuarterly').classList.toggle('active', b === 'quarterly');
  g('billQuarterly').setAttribute('aria-pressed', b === 'quarterly');
  g('billAnnual').classList.toggle('active', b === 'annual');
  g('billAnnual').setAttribute('aria-pressed', b === 'annual');
  render();
}
function setPlan(p) {
  plan = p;
  // Update UI active state
  ['starter', 'growth', 'pro'].forEach(k => {
    const cap = k[0].toUpperCase() + k.slice(1);
    g('plan' + cap).classList.toggle('active', k === p);
    g('plan' + cap).setAttribute('aria-pressed', k === p);
  });
  // 🔥 Apply default values for selected plan
  const defaults = PLAN_DEFAULTS[p];
  if (defaults) {
    g('teamSize').value = defaults.teamSize;
    g('manualHours').value = defaults.manualHours;
    g('hourlyRate').value = defaults.hourlyRate;
    g('toolCost').value = defaults.toolCost;
  }
  if (!interacted) {
    interacted = true;
    fire('roi_calculator_start');
  }
  render();
}
function applyPreset(key) {
  const p = PRESETS[key];
  g('teamSize').value = p.teamSize;
  g('manualHours').value = p.manualHours;
  g('hourlyRate').value = p.hourlyRate;
  g('toolCost').value = p.toolCost;
  document.querySelectorAll('.bt-preset').forEach(b => {
    b.classList.toggle('active', b.dataset.preset === key);
    b.setAttribute('aria-pressed', b.dataset.preset === key);
  });
  if (!interacted) {
    interacted = true;
    fire('roi_calculator_start');

